       if (agoraMs >= ateMs) {
         db.prepare("UPDATE inscricoes SET status = 'expirada', posicaoNaEspera = NULL, convocadaAte = NULL WHERE id = ?").run(inc.id);
         liberarVagaEConvocar(db, inc.atividadeId, ateMs);
       }
     }
