const { test } = require('node:test');
const assert = require('node:assert/strict');
const { criarServidor } = require('../src/servidor');

test('GET /certificados/:codigo com código válido retorna 200', async () => {
    const { app } = await criarServidor();

    // Supondo que um certificado já existe e temos seu código (devemos criar um cenário antes)
    // Para simplificar, vou precisar consultar um código que já sei que existe ou criar.
    // Como a fatia 1 implementou a emissão, assumirei que posso criar um.

    // ... setup: criar participante, atividade, emitir certificado ...
    // Para este teste, focarei apenas na parte pública da R5.
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { criarServidor } from '../src/server.js';

test('GET /certificados/:codigo com código válido retorna 200 (R5)', async () => {
  process.env.MODO_TESTE = '1';
  const { app, porta } = await criarServidor(0);

  try {
    await fetch(`http://localhost:${porta}/_teste/reset`, { method: 'POST' });

    // 1. Setup: Criar atividade e emitir certificado para obter um código válido
    await fetch(`http://localhost:${porta}/_teste/atividades`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-Usuario': 'org-ana' },
      body: JSON.stringify({
        id: 'atv_fatia3_1',
        titulo: 'Palestra para Teste',
        tipo: 'palestra',
        salaId: 'auditorio',
        vagas: 50,
        encontros: [{ id: 'enc_f3', inicio: '2026-10-19T10:00:00-03:00', fim: '2026-10-19T12:00:00-03:00' }],
        cancelada: 0
      })
    });

    await fetch(`http://localhost:${porta}/_teste/relogio`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ agora: '2026-10-19T13:00:00-03:00' })
    });

    await fetch(`http://localhost:${porta}/atividades/atv_fatia3_1/inscricoes`, {
      method: 'POST',
      headers: { 'X-Usuario': 'p-joao' }
    });

    await fetch(`http://localhost:${porta}/encontros/enc_f3/presencas/manual`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-Usuario': 'org-ana' },
      body: JSON.stringify({ participanteId: 'p-joao', justificativa: 'ok' })
    });

    const resEmissao = await fetch(`http://localhost:${porta}/atividades/atv_fatia3_1/certificado`, {
      method: 'POST',
      headers: { 'X-Usuario': 'p-joao' }
    });
    const cert = await resEmissao.json();
    const codigo = cert.codigo;

    // 2. Testar a rota pública
    const res = await fetch(`http://localhost:${porta}/certificados/${codigo.toLowerCase()}`);

    assert.equal(res.status, 200);
    const data = await res.json();
    assert.equal(data.codigo, codigo);
    assert.equal(data.participante, 'Joao Silva'); // Nome do participante conforme se espera no sistema
    assert.equal(data.atividade, 'Palestra para Teste');
  } finally {
    app.close();
  }
});

